protected void processQueryRun()
{
    METProcMetrics procMetrics = METProcMetrics::construct(METBatchLogOperation::TAMCustVendRebatePost);

    using (METProcMetricsScope procMetricsScope = METProcMetricsScope::constructWithErrorHandling(procMetrics))
    {
        if (!query)
        {
            throw error(Error::wrongUseOfFunction(funcName()));
        }

        QueryRun queryRun = new QueryRun(query);
        procMetrics.setTotalCountFromQuery(queryRun);
        procMetrics.setDescription2('Process Started');
        procMetrics.beginTrace();

        next processQueryRun();

        procMetrics.endTrace();
    }

}
